const source = $('Build Queue Review Query').first()?.json ?? {};
const row = $input.first()?.json ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const escapeHtml = (value) => clean(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const parseMaybe = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
};
const formatDateTime = (value) => {
  const raw = clean(value);
  if (!raw) return 'Not available';
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw;
  return date.toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' });
};
const batchId = clean(row.batch_id || source.batch_id);
const hasBatch = row.batch_exists === true || clean(row.status) !== '';
const status = clean(row.status) || 'Unknown';
const canEditItems = status === 'Processing';
const items = parseMaybe(row.items, []);
const packageGroups = parseMaybe(row.package_groups, []);
const selectedTargetMembership = clean(source.target_membership);
const createdAt = clean(row.created_at) ? formatDateTime(row.created_at) : 'Not available';
const completedAt = clean(row.completed_at) ? formatDateTime(row.completed_at) : 'Not completed';
const n8nBaseUrl = clean(source.n8n_base_url) || 'http://n8n:5678';
const actionsUrl = `${n8nBaseUrl}/webhook/signup-batch-actions?batch_id=${encodeURIComponent(batchId)}`;
const reviewBaseUrl = `${n8nBaseUrl}/webhook/clubspark-package-import-queue-review`;
const cancelBaseUrl = `${n8nBaseUrl}/webhook/cancel-clubspark-package-import-item`;
const exportBaseUrl = `${n8nBaseUrl}/webhook/clubspark-package-import-queue-export`;
const markImportedBaseUrl = `${n8nBaseUrl}/webhook/mark-clubspark-package-import-items-imported`;
const summaryCards = [
  { label: 'Status', value: status },
  { label: 'Created', value: createdAt },
  { label: 'Completed', value: completedAt },
  { label: 'Queued', value: String(row.queued_rows ?? 0) },
  { label: 'Exported', value: String(row.exported_rows ?? 0) },
  { label: 'Imported', value: String(row.imported_rows ?? 0) },
  { label: 'Cancelled', value: String(row.cancelled_rows ?? 0) },
  { label: 'Total Rows', value: String(row.total_rows ?? 0) }
];
const selectedGroup = Array.isArray(packageGroups) ? packageGroups.find((group) => clean(group.target_membership) === selectedTargetMembership) ?? null : null;
const selectedPackageId = clean(selectedGroup?.clubspark_package_id);
const selectedImportUrl = clean(selectedGroup?.clubspark_import_url);
const packageFilterCards = Array.isArray(packageGroups) && packageGroups.length
  ? packageGroups.map((group) => {
      const targetMembership = clean(group.target_membership);
      const href = `${reviewBaseUrl}?batch_id=${encodeURIComponent(batchId)}&target_membership=${encodeURIComponent(targetMembership)}`;
      const isSelected = selectedTargetMembership && targetMembership === selectedTargetMembership;
      const classes = `package-chip${isSelected ? ' selected' : ''}`;
      const mappingText = clean(group.clubspark_package_id) ? `Mapped to ${clean(group.clubspark_package_id)}` : 'Missing ClubSpark package mapping';
      return `<a class="${classes}" href="${href}"><strong>${escapeHtml(targetMembership || 'Unspecified')}</strong><span>${escapeHtml(`Queued ${clean(group.queued_rows || 0)} · Exported ${clean(group.exported_rows || 0)} · Imported ${clean(group.imported_rows || 0)}`)}</span><span class="mapping-note${clean(group.clubspark_package_id) ? '' : ' missing'}">${escapeHtml(mappingText)}</span></a>`;
    }).join('')
  : '<div class="empty-filter">No target packages queued in this batch yet.</div>';
const clearFilterLink = selectedTargetMembership ? `<a class="button secondary" href="${reviewBaseUrl}?batch_id=${encodeURIComponent(batchId)}">Show All Packages</a>` : '';
const exportEligibleItems = Array.isArray(items) ? items.filter((item) => clean(item.target_membership) === selectedTargetMembership && ['queued', 'exported'].includes(clean(item.status))) : [];
const importEligibleItems = Array.isArray(items) ? items.filter((item) => clean(item.target_membership) === selectedTargetMembership && clean(item.status) === 'exported') : [];
const showSelectionForm = Boolean(selectedTargetMembership) && canEditItems && ((Boolean(selectedPackageId) && exportEligibleItems.length > 0) || importEligibleItems.length > 0);
const showExportButton = Boolean(selectedTargetMembership) && canEditItems && Boolean(selectedPackageId) && exportEligibleItems.length > 0;
const showImportButton = Boolean(selectedTargetMembership) && canEditItems && importEligibleItems.length > 0;
const itemRows = Array.isArray(items) ? items.map((item, index) => {
  const queueId = clean(item.id);
  const itemStatus = clean(item.status);
  const rawMemberExists = item.raw_member_exists === true || clean(item.raw_member_exists).toLowerCase() === 'true';
  const rawMemberCurrent = item.raw_member_is_current === true || clean(item.raw_member_is_current).toLowerCase() === 'true';
  const canCancel = canEditItems && itemStatus !== 'cancelled' && itemStatus !== 'imported';
  const canSelect = showSelectionForm && clean(item.target_membership) === selectedTargetMembership && ['queued', 'exported'].includes(itemStatus);
  const memberState = !rawMemberExists ? 'Missing from raw_members' : rawMemberCurrent ? `Current row (${clean(item.current_membership || item.source_membership || 'No membership')})` : 'Historic raw_members row';
  const selectionHtml = canSelect ? `<input class="checkbox-input" type="checkbox" name="item_id" value="${escapeHtml(queueId)}"${itemStatus === 'queued' ? ' checked' : ''}>` : '<span class="action-note">-</span>';
  let actionHtml = '<span class="action-note">No action</span>';
  if (canCancel) {
    actionHtml = `<a class="table-action danger" href="${cancelBaseUrl}?batch_id=${encodeURIComponent(batchId)}&item_id=${encodeURIComponent(queueId)}">Cancel</a>`;
  } else if (itemStatus === 'cancelled') {
    actionHtml = '<span class="action-note">Cancelled</span>';
  } else if (itemStatus === 'imported') {
    actionHtml = '<span class="action-note">Imported</span>';
  } else if (!canEditItems) {
    actionHtml = '<span class="action-note">Editable only while Processing</span>';
  }
  const statusClass = itemStatus === 'queued' ? 'badge-queued' : itemStatus === 'exported' ? 'badge-exported' : itemStatus === 'imported' ? 'badge-imported' : 'badge-cancelled';
  return `<tr><td class="checkbox-cell">${selectionHtml}</td><td>${index + 1}</td><td>${escapeHtml(queueId)}</td><td><span class="badge ${statusClass}">${escapeHtml(itemStatus || 'unknown')}</span></td><td>${escapeHtml(item.member || '')}</td><td>${escapeHtml(item.source_membership || '')}</td><td>${escapeHtml(item.target_membership || '')}</td><td>${escapeHtml(item.email_address || '')}</td><td>${escapeHtml(memberState)}</td><td>${escapeHtml(clean(item.british_tennis_number) || '')}</td><td>${escapeHtml(formatDateTime(item.created_at))}</td><td>${escapeHtml(clean(item.export_file_name) || 'Not exported')}</td><td>${escapeHtml(item.notes || '')}</td><td class="action-cell">${actionHtml}</td></tr>`;
}).join('') : '';
const filterSummary = selectedTargetMembership ? `<p class="filter-summary">Filtered to target package <strong>${escapeHtml(selectedTargetMembership)}</strong>.</p>` : '<p class="filter-summary">Showing all queued target packages in this batch.</p>';
let exportPanelHtml = '';
if (selectedTargetMembership) {
  const mappingHtml = selectedPackageId ? `<div class="export-meta-card"><span>ClubSpark Package ID</span><strong>${escapeHtml(selectedPackageId)}</strong></div><div class="export-meta-card"><span>Import Destination</span><a href="${escapeHtml(selectedImportUrl)}" target="_blank" rel="noreferrer">${escapeHtml(selectedImportUrl)}</a></div>` : `<div class="export-meta-card"><span>Import Mapping</span><strong>Missing ClubSpark package mapping</strong></div>`;
  let exportMessage = 'Tick the rows to include, then download the external-file workbook for this one ClubSpark package. After the ClubSpark upload succeeds, tick the exported rows and mark them imported here.';
  if (!canEditItems) exportMessage = 'Exports and imported-status updates are locked because the batch is no longer Processing.';
  else if (!selectedPackageId && !importEligibleItems.length) exportMessage = 'This target package cannot be exported yet because it does not have a mapped ClubSpark package ID.';
  else if (!exportEligibleItems.length && !importEligibleItems.length) exportMessage = 'There are no queued or exported rows available for this package filter.';
  exportPanelHtml = `<section class="panel export-panel"><strong>Package Export</strong><p>${escapeHtml(exportMessage)}</p><div class="export-meta">${mappingHtml}<div class="export-meta-card"><span>Eligible For Export</span><strong>${escapeHtml(String(exportEligibleItems.length))}</strong></div><div class="export-meta-card"><span>Eligible For Imported Status</span><strong>${escapeHtml(String(importEligibleItems.length))}</strong></div></div></section>`;
}
const actionButtons = [
  `<span>${escapeHtml(String(Array.isArray(items) ? items.length : 0))} rows</span>`
];
if (showSelectionForm) {
  actionButtons[0] = `<span>${escapeHtml(String(exportEligibleItems.length))} export-eligible · ${escapeHtml(String(importEligibleItems.length))} import-eligible</span>`;
  if (showExportButton) actionButtons.push(`<button class="button" type="submit">Download XLSX</button>`);
  if (showImportButton) actionButtons.push(`<button class="button secondary" type="submit" formaction="${markImportedBaseUrl}">Mark Imported</button>`);
}
const tableHeaderActions = showSelectionForm ? `<div class="table-actions">${actionButtons.join('')}</div>` : `<span>${escapeHtml(String(Array.isArray(items) ? items.length : 0))} rows</span>`;
const tableOpen = showSelectionForm ? `<form class="export-form" method="post" action="${exportBaseUrl}"><input type="hidden" name="batch_id" value="${escapeHtml(batchId)}"><input type="hidden" name="target_membership" value="${escapeHtml(selectedTargetMembership)}">` : '';
const tableClose = showSelectionForm ? '</form>' : '';
const body = hasBatch ? `
  <section class="hero">
    <div><h1>Batch ${escapeHtml(batchId)} ClubSpark Queue</h1><p class="lede">Review queued existing-member package imports for this batch. Queue rows stay separate from manual shoe-tag and key items.</p>${filterSummary}</div>
    <div class="hero-actions">${clearFilterLink}<a class="button secondary" href="${actionsUrl}">Back to Actions</a><button type="button" class="button secondary" onclick="window.close()">Close</button></div>
  </section>
  <section class="summary-grid">${summaryCards.map((card) => `<div class="summary-card"><h2>${escapeHtml(card.label)}</h2><p>${escapeHtml(card.value)}</p></div>`).join('')}</section>
  <section class="panel note-panel"><strong>Target package groups</strong><p>Do not mix different target memberships into the same ClubSpark upload. Use these package groups to review and export one package at a time.</p><div class="package-chips">${packageFilterCards}</div></section>
  ${exportPanelHtml}
  <section class="panel table-panel">${tableOpen}<div class="table-header"><h2>Queued Import Rows</h2>${tableHeaderActions}</div><div class="table-wrap"><table><thead><tr><th>Select</th><th>#</th><th>Queue ID</th><th>Status</th><th>Member</th><th>Current Package</th><th>Target Package</th><th>Email</th><th>Raw Member State</th><th>BTN</th><th>Queued</th><th>Export File</th><th>Notes</th><th>Action</th></tr></thead><tbody>${itemRows || '<tr><td colspan="14">No ClubSpark package queue rows found for this batch.</td></tr>'}</tbody></table></div>${tableClose}</section>` : `
  <section class="hero"><div><h1>ClubSpark Queue Review</h1><p class="lede">The batch could not be resolved from the request.</p></div><div class="hero-actions"><button type="button" class="button secondary" onclick="window.close()">Close</button></div></section>
  <section class="panel note-panel"><strong>Missing or invalid batch ID</strong><p>Open this page from the batch actions link so the batch ID is supplied automatically.</p></section>`;
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${hasBatch ? `Batch ${escapeHtml(batchId)} ClubSpark Queue` : 'ClubSpark Queue Review'}</title><style>:root{color-scheme:light;--bg:#f7f8fc;--panel:#ffffff;--ink:#2e3d4e;--muted:#6b7785;--line:#e2e8f0;--accent:#509ee3;--soft:#f2f7fd;--queued:#eef6ff;--queued-ink:#1d4ed8;--exported:#fff7ed;--exported-ink:#9a3412;--imported:#ecfdf3;--imported-ink:#166534;--cancelled:#fef2f2;--cancelled-ink:#b42318;--button-soft:#eef2f7;--danger:#b42318}*{box-sizing:border-box}body{margin:0;font-family:Lato,'Helvetica Neue',Arial,sans-serif;color:var(--ink);background:linear-gradient(180deg,#fbfcfe 0%,var(--bg) 100%);padding:24px}.wrap{max-width:1440px;margin:0 auto;display:grid;gap:18px}.hero,.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 18px 40px rgba(53,72,91,.08)}.hero{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{margin:0 0 6px;font-size:34px;line-height:1.05;letter-spacing:-.02em}h2{margin:0;font-size:20px}.lede,.filter-summary{margin:0;color:var(--muted);font-size:16px;max-width:860px;line-height:1.6}.filter-summary{margin-top:10px}.hero-actions{display:flex;gap:10px;flex-wrap:wrap}.button{appearance:none;border:0;border-radius:999px;padding:11px 16px;font:inherit;font-weight:700;text-decoration:none;cursor:pointer;color:#fff;background:linear-gradient(135deg,var(--accent) 0%,#2f80d8 100%);box-shadow:0 10px 24px rgba(80,158,227,.22)}.button.secondary{color:var(--ink);background:var(--button-soft);border:1px solid var(--line);box-shadow:none}.summary-grid{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(160px,1fr))}.summary-card{border:1px solid var(--line);border-radius:14px;padding:16px;background:var(--soft)}.summary-card h2{margin:0 0 8px;font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.summary-card p{margin:0;font-size:20px;line-height:1.3}.note-panel strong{display:block;margin-bottom:6px;font-size:16px}.note-panel p{margin:0;color:var(--muted);line-height:1.6}.package-chips{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px}.package-chip,.empty-filter{display:grid;gap:4px;min-width:240px;padding:14px 16px;border-radius:14px;border:1px solid var(--line);text-decoration:none;background:#f8fafc;color:var(--ink)}.package-chip strong{font-size:16px}.package-chip span,.empty-filter{color:var(--muted);font-size:14px;line-height:1.5}.package-chip.selected{border-color:#7fb4ea;background:#eef6ff;box-shadow:0 10px 24px rgba(80,158,227,.12)}.mapping-note{font-weight:700;color:var(--ink)}.mapping-note.missing{color:var(--danger)}.export-panel{display:grid;gap:12px}.export-meta{display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin-top:12px}.export-meta-card{border:1px solid var(--line);border-radius:14px;padding:14px 16px;background:#f8fafc}.export-meta-card span{display:block;margin-bottom:6px;color:var(--muted);font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.04em}.export-meta-card strong,.export-meta-card a{font-size:15px;line-height:1.5;color:var(--ink);word-break:break-word}.export-form{display:grid;gap:0}.table-panel{padding:0;overflow:hidden}.table-header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:20px 24px 12px;flex-wrap:wrap}.table-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.table-header span{color:var(--muted);font-weight:700}.table-wrap{overflow:auto;border-top:1px solid var(--line)}table{width:100%;border-collapse:collapse;min-width:1460px}th,td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;font-size:14px}th{position:sticky;top:0;background:#f8fafc;z-index:1;font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}tbody tr:nth-child(even){background:#fcfdff}.checkbox-cell{width:44px;text-align:center}.checkbox-input{width:16px;height:16px;accent-color:var(--accent)}.badge{display:inline-flex;align-items:center;padding:4px 10px;border-radius:999px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;border:1px solid transparent}.badge-queued{background:var(--queued);color:var(--queued-ink);border-color:#bfdbfe}.badge-exported{background:var(--exported);color:var(--exported-ink);border-color:#fdba74}.badge-imported{background:var(--imported);color:var(--imported-ink);border-color:#86efac}.badge-cancelled{background:var(--cancelled);color:var(--cancelled-ink);border-color:#fca5a5}.action-cell{white-space:nowrap}.table-action{display:inline-flex;align-items:center;justify-content:center;padding:8px 12px;border-radius:999px;text-decoration:none;font-size:13px;font-weight:700;border:1px solid transparent}.table-action.danger{color:var(--danger);background:#fef3f2;border-color:#fecdca}.action-note{color:var(--muted);font-size:13px;font-weight:600}@media (max-width:900px){body{padding:16px}.hero,.panel{padding:18px}.table-header{padding:18px 18px 10px}.package-chip,.empty-filter{min-width:100%}}</style></head><body><div class="wrap">${body}</div></body></html>`;
return [{ json: { html } }];
